const userId = input.user?.id || input.userId;
const contextResponse = await httpJson(staffContextUrl, {
  method: 'POST',
  headers: agentHeaders,
  body: { userId, user: input.user, sessionId: input.sessionId, message: query },
});
if (!contextResponse.ok) {
  throw new Error(contextResponse.body?.error || 'Unable to load Steve platform context');
}
const platformContext = contextResponse.body || {};
const embedResponse = await httpJson('https://generativelanguage.googleapis.com/v1beta/models/' + embeddingModel + ':embedContent', {
  method: 'POST',
  headers: {
    'content-type': 'application/json',
    'x-goog-api-key': $env.GEMINI_API_KEY,
  },
  body: {
    content: { parts: [{ text: query }] },
    output_dimensionality: 768,
  },
