const embedBody = embedResponse.body;
if (!embedResponse.ok) {
  throw new Error(embedBody?.error?.message || 'Gemini embedding request failed');
}
const embedding = embedBody?.embedding?.values || embedBody?.embeddings?.[0]?.values;
const ragResponse = await httpJson(ragSearchUrl, {
  method: 'POST',
  headers: agentHeaders,
  body: { query, embedding, limit: 8 },
});
const ragBody = ragResponse.body;
if (!ragResponse.ok) {
  throw new Error(ragBody?.error || 'RAG search failed');
}
const retrievedDocuments = [...(platformContext.ragResults || []), ...(ragBody.results || [])].slice(0, 12);
const retrievedText = retrievedDocuments.map((doc, index) => 'Document ' + (index + 1) + ': ' + (doc.entityType || doc.entity_type) + ' ' + (doc.entityId || doc.entity_id) + '\n' + String(doc.content || '').slice(0, 3500)).join('\n\n');
const historyText = Array.isArray(input.history) ? input.history.map((item) => item.role + ': ' + item.content).join('\n').slice(-6000) : '';
