const system = 'You are Steve, the STI Risk platform intelligence assistant. You help authenticated staff work across deals, contacts, growth, projects, and tasks. Use only supplied STI Risk context, RAG, conversation history, and uploaded text. Be direct and operational. You may request at most one tool action. Allowed actions: ' + (allowedActions.join(', ') || 'none') + '. Direct writes are limited to internal tasks, task comments, and internal communication notes. Deal/contact/project/growth changes must be approval-first recommendations. Do not send outreach, enroll contacts, change pricing, make finance decisions, or perform destructive actions. Return only JSON with keys: reply, action, actionPayload, requiresApproval, reason.';
const prompt = 'Current Steve context:\n' + (platformContext.context || input.context || '') + '\n\nStructured platform data:\n' + platformData + '\n\nRecent conversation:\n' + historyText + '\n\nRetrieved STI Risk platform memory:\n' + (retrievedText || 'No RAG documents matched.') + '\n\nUploaded document text:\n' + (attachmentText || 'No uploaded text.') + '\n\nUser request:\n' + query;
const chatResponse = await httpJson('https://generativelanguage.googleapis.com/v1beta/models/' + chatModel + ':generateContent', {
  method: 'POST',
  headers: {
    'content-type': 'application/json',
    'x-goog-api-key': $env.GEMINI_API_KEY,
  },
  body: {
    system_instruction: { parts: [{ text: system }] },
    contents: [{ role: 'user', parts: [{ text: prompt }] }],
