  },
});
const chatBody = chatResponse.body;
if (!chatResponse.ok) {
  throw new Error(chatBody?.error?.message || 'Gemini chat request failed');
}
const rawContent = (chatBody.candidates?.[0]?.content?.parts || []).map((part) => part.text || '').join('').trim();
const decision = parseDecision(rawContent) || {
  reply: rawContent || 'Steve did not return a text response.',
  action: null,
  actionPayload: null,
