if (requestedAction) {
  const actionResponse = await httpJson(staffActionsUrl, {
    method: 'POST',
    headers: agentHeaders,
    body: {
      userId,
      user: input.user,
      sessionId: input.sessionId,
      action: requestedAction,
      payload: decision.actionPayload || {},
    },
  });
  actionResult = actionResponse.body;
  if (!actionResponse.ok) {
    const fallbackResponse = await httpJson(staffActionsUrl, {
      method: 'POST',
      headers: agentHeaders,
      body: {
        userId,
        user: input.user,
        sessionId: input.sessionId,
        action: 'create_recommendation',
        payload: {
          title: 'Steve action requires review',
          body: String(decision.reply || 'Steve proposed an action.') + '\n\nAction failed: ' + (actionResponse.body?.error || actionResponse.status),
          recommendationType: 'steve_chat_action_review',
          metadata: { requestedAction, reason: decision.reason || null },
        },
      },
    });
    actionResult = fallbackResponse.body;
  }
}
const suffix = actionResult?.taskId
  ? '\n\nTask created: ' + actionResult.taskId
  : actionResult?.commentId
    ? '\n\nTask comment added: ' + actionResult.commentId
    : actionResult?.communicationId
      ? '\n\nInternal note logged: ' + actionResult.communicationId
      : actionResult?.recommendationId
        ? '\n\nApproval recommendation created: ' + actionResult.recommendationId
        : '';
const content = String(decision.reply || 'Steve completed the review.').trim() + suffix;
return [{ json: { sessionId: input.sessionId, message: { role: 'assistant', content }, usage: chatBody.usageMetadata || null, retrievedDocuments, actionResult, requestedAction } }];
